import React, { useState } from 'react';
import Header from './Header';
import './UserPage.css';
import Footer from './Footer';
import saree1 from './saree.jpg';  // Image source for the product

const UserPage = () => {
    // Define static past orders for the user
    const [pastOrders] = useState([
        {
            orderId: 1,
            date: "2024-10-10",
            items: [
                { name: 'Traditional Silk Saree', price: 4500, quantity: 2, imageUrl: saree1 },
                { name: 'Cotton Saree', price: 3000, quantity: 1, imageUrl: saree1 }
            ]
        },
        {
            orderId: 2,
            date: "2024-09-25",
            items: [
                { name: 'Chiffon Saree', price: 3500, quantity: 1, imageUrl: saree1 }
            ]
        }
    ]);

    // Calculate total price for each past order
    const calculateOrderTotal = (items) => {
        return items.reduce((total, item) => total + item.price * item.quantity, 0);
    };

    return (
        <div className='UserPage'>
            <Header />
            <h1>User Info</h1>

            {/* User Details Table */}
            <table className='UserTable'>
                <tr width='100%'></tr>
                <td className='column1User' width='20%'>
                    <div className='Basics'>
                        <tr><td>Username:</td><td>Nithya.P</td></tr>
                        <tr><td>Password:</td><td>******</td></tr>
                        <tr><td>Email:</td><td>NithyaP@mail.com</td></tr>
                        <tr><td>Phone:</td><td>1234567890</td></tr>
                    </div>
                </td>  
                <td className='column2User' width='80%'>  
                    <div className='Address'>
                        <tr><td>Current Address:</td><td>123, 1st main, 4th block, Jaynagar, Bangalore, India</td></tr>
                        <button>Change Address</button>
                    </div>
                </td>  
            </table>
            <hr className="hr" />

            {/* Past Orders Section */}
            <div className='PastHistory'>
                <h3>Past Orders</h3>

                {/* Display Each Past Order */}
                {pastOrders.map((order) => (
                    <div key={order.orderId} className="order-card">
                        <h4>Order ID: {order.orderId}</h4>
                        <p>Date of Purchase: {order.date}</p>

                        {/* Display Items in Each Order */}
                        <div className="order-items">
                            {order.items.map((item, index) => (
                                <div key={index} className="order-item">
                                    <img src={item.imageUrl} alt={item.name} className="order-item-image" />
                                    <div className="order-item-details">
                                        <p>{item.name}</p>
                                        <p>Price: ₹{item.price}</p>
                                        <p>Quantity: {item.quantity}</p>
                                        <p>Total: ₹{item.price * item.quantity}</p>
                                    </div>
                                </div>
                            ))}
                        </div>

                        {/* Display Order Total */}
                        <div className="order-total">
                            <p><strong>Total: ₹{calculateOrderTotal(order.items)}</strong></p>
                        </div>
                    </div>
                ))}
            </div>

            <Footer />
        </div>
    );
};

export default UserPage;
